BFS (N, A, n₀, ĐICH)
{
    fringe ← n₀;
    closed ← ∅;
    while (fringe ≠ ∅) do
    {    n ← GET_FIRST(fringe);          // lấy phần tử đầu tiên của fringe
        closed ← closed ⊕ n;
        if (n ∈ ĐICH) then return SOLUTION(n);
        if (Γ(n) ≠ ∅) then fringe ← fringe ⊕ Γ(n);
    }
    return (“No solution”);
}
```

